        let name = url.rsplit('/').next().unwrap();
        self.files
            .get(name)
            .cloned()
            .ok_or_else(|| format!("missing {name}"))
            .map(|s| s.into_bytes())
    }
}

fn sha256_hex(s: &str) -> String {
    let mut h = Sha256::new();
    h.update(s.as_bytes());
    format!("{:x}", h.finalize())
}

