    use super::*;

    struct MemFetch {
        files: HashMap<String, Vec<u8>>,
    }

    impl Fetch for MemFetch {
        fn get(&self, url: &str) -> Result<Vec<u8>, String> {
            self.files.get(url).cloned().ok_or_else(|| format!("no {url}"))
        }
    }

    #[test]
    fn swap_renames_staged_files_into_place() {
        let dir = tempfile::tempdir().unwrap();
        let wc = working_copy_dir(dir.path());
        std::fs::create_dir_all(&wc).unwrap();
        // One file unchanged (stays), one staged.
        std::fs::write(wc.join("speech.json"), "old-speech").unwrap();
        std::fs::write(wc.join("llm.json"), "old-llm").unwrap();
        std::fs::write(wc.join("command.json"), "old-cmd").unwrap();
        let speech = "old-speech";
        let llm = "new-llm";
        let command = "old-cmd";
        let manifest: Manifest = serde_json::from_str(&format!(
            r#"{{ "version": 7, "files": {{ "speech": "{}", "llm": "{}", "command": "{}" }}, "url": "https://x.example/base" }}"#,
            sha256_hex(speech.as_bytes()),
            sha256_hex(llm.as_bytes()),
            sha256_hex(command.as_bytes()),
        ))
        .unwrap();
        // Stub: manifest + only the changed llm file.
        let mut files = HashMap::new();
        files.insert(MANIFEST_URL.to_string(), serde_json::to_vec(&manifest).unwrap());
        files.insert(
            format!("{}/llm.json", manifest.url),
            llm.as_bytes().to_vec(),
        );
        let res = try_update(dir.path(), &MemFetch { files });
        assert!(matches!(res, UpdateResult::Updated));
        assert_eq!(std::fs::read_to_string(wc.join("llm.json")).unwrap(), "new-llm");
        assert_eq!(std::fs::read_to_string(wc.join("speech.json")).unwrap(), "old-speech");
        assert_eq!(
            std::fs::read_to_string(wc.join("version")).unwrap(),
            "7"
        );
        // No temp files left behind.
        for key in CATALOG_FILES {
            assert!(!wc.join(format!("{key}.json.tmp")).exists());
        }
    }
}

